                    nxt[target] = (nxt[target] + ways * multiplicity) % mod
        dp = nxt
    answer = [0] * (n + 1)
    for row, ways in enumerate(dp):
        length = row.bit_count()
        answer[length] = (answer[length] + ways) % mod
    return answer

