from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    """Maximize bounded product of a nonempty subsequence with alternating sum k."""
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    offset = bound
    overflow = limit + 1
    even = {}
    odd = {}
    for value in nums:
        # Keep products above limit: selecting a later zero makes them valid.
        following_even = even.copy()
        following_odd = odd.copy()
        for product, sums in even.items():
            target = min(overflow, product * value)
            following_odd[target] = following_odd.get(target, 0) | (sums << value)
        for product, sums in odd.items():
            target = min(overflow, product * value)
            following_even[target] = following_even.get(target, 0) | (sums >> value)
        target = min(overflow, value)
        following_odd[target] = following_odd.get(target, 0) | (1 << (offset + value))
        even, odd = following_even, following_odd
    wanted = 1 << (offset + k)
    return max((product for product in even.keys() | odd.keys()
                if product <= limit and ((even.get(product, 0) | odd.get(product, 0)) & wanted)),
               default=-1)

