from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    offset = sum(nums)
    if abs(k) > offset:
        return -1
    overflow = limit + 1
    even = {}
    odd = {}
    for value in nums:
        next_even = even.copy()
        next_odd = odd.copy()
        for product, bits in even.items():
            new_product = min(product * value, overflow)
            next_odd[new_product] = next_odd.get(new_product, 0) | (bits << value)
        for product, bits in odd.items():
            new_product = min(product * value, overflow)
            next_even[new_product] = next_even.get(new_product, 0) | (bits >> value)
        product = min(value, overflow)
        next_odd[product] = next_odd.get(product, 0) | (1 << (offset + value))
        even, odd = next_even, next_odd
    target = 1 << (offset + k)
    answer = -1
    for states in (even, odd):
        for product, bits in states.items():
            if product <= limit and bits & target:
                answer = max(answer, product)
    return answer

