from typing import List


def count_strings_by_lcs_length(n: int, m: int, s: str) -> List[int]:
    """Count length-m lowercase strings by LCS length with s, modulo 998244353."""
    mod = 998244353
    size = 1 << n
    groups = {}
    for code in range(26):
        matches = 0
        char = chr(97 + code)
        for i, value in enumerate(s):
            if value == char:
                matches |= 1 << i
        groups[matches] = groups.get(matches, 0) + 1

    # A bit records an increase between adjacent entries of an LCS row.
    # Updating this row by a character uses the bit-parallel LCS recurrence.
    transitions = []
    for state in range(size):
        counts = {}
        for matches, multiplicity in groups.items():
            x = state | matches
            following = x & ~(x - ((state << 1) | 1))
            counts[following] = counts.get(following, 0) + multiplicity
        transitions.append(list(counts.items()))

    dp = [0] * size
    dp[0] = 1
    for _ in range(m):
        following_dp = [0] * size
        for state, count in enumerate(dp):
            if count:
                for following, multiplicity in transitions[state]:
                    following_dp[following] += count * multiplicity
        dp = [count % mod for count in following_dp]

    result = [0] * (n + 1)
    for state, count in enumerate(dp):
        length = state.bit_count()
        result[length] = (result[length] + count) % mod
    return result

