from typing import List

def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    bound = sum(nums)
    if abs(k) > bound:
        return -1
    mask = (1 << (2*bound+1)) - 1
    overflow = limit + 1
    dp = {}
    for value in nums:
        nxt = dp.copy()
        for product, (even, odd) in dp.items():
            target = min(overflow, product*value)
            old_even, old_odd = nxt.get(target, (0, 0))
            nxt[target] = (old_even | (odd >> value),
                           old_odd | ((even << value) & mask))
        target = min(overflow, value)
        old_even, old_odd = nxt.get(target, (0, 0))
        nxt[target] = (old_even, old_odd | (1 << (bound+value)))
        dp = nxt
    bit = 1 << (bound+k)
    return max((p for p, (even, odd) in dp.items()
                if p <= limit and (even | odd) & bit), default=-1)

