from typing import List


def max_product_subsequence(nums: List[int], k: int, limit: int) -> int:
    offset = sum(nums)
    if abs(k) > offset:
        return -1
    # Product -> (even-length sums, odd-length sums), encoded as bitsets.
    # limit+1 represents all oversized products; a later zero resets them.
    overflow = limit + 1
    states = {}
    for x in nums:
        nxt = states.copy()
        for product, (even, odd) in states.items():
            target = min(product * x, overflow)
            old_even, old_odd = nxt.get(target, (0, 0))
            nxt[target] = (old_even | (odd >> x), old_odd | (even << x))
        target = min(x, overflow)
        old_even, old_odd = nxt.get(target, (0, 0))
        nxt[target] = (old_even, old_odd | (1 << (offset + x)))
        states = nxt
    wanted = 1 << (offset + k)
    return max((product for product, (even, odd) in states.items()
