def count_valid_grids(H: int, W: int, grid: list[str]) -> int:
    """Count proper three-colour completions modulo 998244353.

    Adjacent edge-sharing cells must contain different digits. The grid has
    H rows, W columns, and at most 200 cells; '?' denotes an unspecified cell.
    """
    mod = 998244353
    # Sweep along the longer dimension so the frontier has at most 14 cells.
    if W > H:
        grid = ["".join(grid[r][c] for r in range(H)) for c in range(W)]
        H, W = W, H

    # Each two-bit slot stores a frontier colour, with zero for cells outside
    # the grid. The oldest slot is directly above the current cell.
    mask = (1 << (2 * W)) - 1
    above_shift = 2 * (W - 1)
    dp = {0: 1}
    for row in grid:
        for col, cell in enumerate(row):
            choices = (1, 2, 3) if cell == "?" else (int(cell),)
            next_dp = {}
            for state, count in dp.items():
                above = (state >> above_shift) & 3
                left = (state & 3) if col else 0
                shifted = (state << 2) & mask
                for colour in choices:
                    if colour != above and colour != left:
                        new_state = shifted | colour
                        next_dp[new_state] = (
                            next_dp.get(new_state, 0) + count
                        ) % mod
            dp = next_dp
            if not dp:
                return 0
    return sum(dp.values()) % mod

