from functools import lru_cache
from math import gcd


@lru_cache(maxsize=None)
def _suffix_count(length: int, digit_sum: int, needed: int) -> int:
    """Count nonzero-digit suffixes with a given sum and product divisor."""
    if length == 0:
        return int(digit_sum == 0 and needed == 1)
    if digit_sum < length or digit_sum > 9 * length:
        return 0
    return sum(
        _suffix_count(length - 1, digit_sum - digit, needed // gcd(needed, digit))
        for digit in range(1, 10)
    )


def _count_up_to(limit: int) -> int:
    if limit <= 0:
        return 0
    digits = [int(char) for char in str(limit)]
    length = len(digits)

    # Every positive number containing a zero is beautiful. Count its
    # complement, and collect the disjoint prefixes for nonzero numbers.
    nonzero_count = sum(9 ** size for size in range(1, length))
    branches = [(size, 0, 1) for size in range(1, length)]
    prefix_sum, prefix_product = 0, 1
    for index, digit in enumerate(digits):
        remaining = length - index - 1
        for smaller in range(1, digit):
            nonzero_count += 9 ** remaining
            branches.append((remaining, prefix_sum + smaller, prefix_product * smaller))
        if digit == 0:
            break
        prefix_sum += digit
        prefix_product *= digit
    else:
        nonzero_count += 1
        branches.append((0, prefix_sum, prefix_product))

    beautiful = limit - nonzero_count
    for remaining, prefix_sum, prefix_product in branches:
        for total in range(prefix_sum + remaining, prefix_sum + 9 * remaining + 1):
            if total == 0:
                continue
            # A nonzero digit product has only these four prime factors.
            residual = total
            for prime in (2, 3, 5, 7):
                while residual % prime == 0:
                    residual //= prime
            if residual != 1:
                continue
            needed = total // gcd(total, prefix_product)
            beautiful += _suffix_count(remaining, total - prefix_sum, needed)
    return beautiful


def count_beautiful_numbers(l: int, r: int) -> int:
    """ Count the number of beautiful numbers in the range [l, r] inclusive.

    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.

    Args:
        l: The lower bound of the range (inclusive)
        r: The upper bound of the range (inclusive)

    Returns:
        The count of beautiful numbers in the range [l, r]

    Constraints:
        1 <= l <= r < 10^9

    >>> count_beautiful_numbers(10, 20)
    2
    >>> count_beautiful_numbers(1, 15)
    10
    >>> count_beautiful_numbers(4, 4)
    1
    """
    return _count_up_to(r) - _count_up_to(l - 1)

