from math import isqrt


def count_power_representations(n: int) -> int:
    """Count integers x in [1, n] expressible as a**b for a >= 1, b >= 2.

    Args:
        n: The upper bound (1 <= n <= 10**18).

    Returns:
        The number of distinct representable integers, including 1.

    >>> count_power_representations(99)
    12
    >>> count_power_representations(1000000000000000000)
    1001003332
    """
    limit = n.bit_length() - 1
    # A value > 1 with prime-factor exponent gcd g is a kth power iff k | g.
    # Thus -sum(mu(k), k | g, k >= 2) is 1 exactly when g > 1.
    mu = [1] * (limit + 1)
    prime = [True] * (limit + 1)
    for p in range(2, limit + 1):
        if prime[p]:
            for multiple in range(p, limit + 1, p):
                prime[multiple] = False
                mu[multiple] = -mu[multiple]
            for multiple in range(p * p, limit + 1, p * p):
                mu[multiple] = 0

    def integer_root(k: int) -> int:
        if k == 2:
            return isqrt(n)
        low, high = 1, 1 << ((n.bit_length() + k - 1) // k)
        while high - low > 1:
            middle = (low + high) // 2
            if middle ** k <= n:
                low = middle
            else:
                high = middle
        return low

    answer = 1  # 1 is a power for every exponent; count it only once.
    for k in range(2, limit + 1):
        if mu[k]:
            answer -= mu[k] * (integer_root(k) - 1)
    return answer

