from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether a subset of the rotatable tiles exactly covers the grid.

    Each tile may be used at most once. Tiles are aligned with grid cells,
    cannot overlap, and cannot extend beyond the h by w board.
    """
    # Discard tiles that cannot fit in either orientation and put larger
    # rectangles first to find large-area coverings early.
    shapes = sorted(
        [(min(a, b), max(a, b)) for a, b in tiles[:n]
         if (a <= h and b <= w) or (b <= h and a <= w)],
        key=lambda shape: shape[0] * shape[1],
        reverse=True,
    )
    count = len(shapes)
    area = h * w
    full = (1 << area) - 1

    # Bit k in subset_areas[mask] means some subset of mask has area k.
    # This permits unused tiles while pruning impossible residual areas.
    subset_areas = [1] * (1 << count)
    for mask in range(1, 1 << count):
        bit = mask & -mask
        i = bit.bit_length() - 1
        smaller = subset_areas[mask ^ bit]
        a, b = shapes[i]
        subset_areas[mask] = smaller | (smaller << (a * b))

    placements = [[[] for _ in shapes] for _ in range(area)]
    for cell in range(area):
        row, col = divmod(cell, w)
        for i, (a, b) in enumerate(shapes):
            orientations = [(a, b)] if a == b else [(a, b), (b, a)]
            for height, width in orientations:
                if row + height <= h and col + width <= w:
                    row_bits = ((1 << width) - 1) << cell
                    rectangle = 0
                    for offset in range(height):
                        rectangle |= row_bits << (offset * w)
                    placements[cell][i].append(rectangle)

    @lru_cache(maxsize=None)
    def search(occupied: int, remaining: int) -> bool:
        if occupied == full:
            return True
        needed = area - occupied.bit_count()
        if not ((subset_areas[remaining] >> needed) & 1):
            return False

        # In any completion the first empty cell is the upper-left corner
        # of its rectangle: an earlier corner would already be occupied.
        empty = full ^ occupied
        cell = (empty & -empty).bit_length() - 1
        seen = set()
        for i, shape in enumerate(shapes):
            bit = 1 << i
            if not remaining & bit or shape in seen:
                continue
            seen.add(shape)
            for rectangle in placements[cell][i]:
                if not occupied & rectangle:
                    if search(occupied | rectangle, remaining ^ bit):
                        return True
        return False

    return search(0, (1 << count) - 1)
